-- 3NF vs BCNF FD Check:
-- 3NF: For X -> Y, X must be a Superkey OR Y must be a Prime Attribute.
-- BCNF: For X -> Y, X MUST be a Superkey (stricter than 3NF).

-- Example Student-Department Schema in 3NF:
CREATE TABLE Department (
    dept_id INT PRIMARY KEY,
    dept_name VARCHAR(100)
);
CREATE TABLE Student (
    student_id INT PRIMARY KEY,
    student_name VARCHAR(100),
    dept_id INT FOREIGN KEY REFERENCES Department(dept_id)
);

-- Transaction Isolation Levels in SQL:
SET TRANSACTION ISOLATION LEVEL REPEATABLE READ;
BEGIN TRANSACTION;
  SELECT * FROM Accounts WHERE id = 101;
  -- Prevents Dirty Reads & Non-Repeatable Reads, but Phantom Reads can occur.
COMMIT;

-- Covering Index Example:
CREATE INDEX idx_emp_dept_salary ON Employee(dept_id, salary, emp_name);
-- Query executes via Index-Only Scan (no base table lookup needed):
SELECT emp_name, salary FROM Employee WHERE dept_id = 5;

-- DELETE (DML): Logged per row, supports WHERE clause, can be rolled back
DELETE FROM Employee WHERE dept_id = 10;

-- TRUNCATE (DDL): Resets identity, removes all rows rapidly, minimal logging
TRUNCATE TABLE Employee;

-- DROP (DDL): Removes data AND table schema structure completely
DROP TABLE Employee;
